1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Single source of truth for an owner's {@code identityKey}, the derived value all duplicate
7	 * detection is expressed through: {@code normalizedTelephone + '|' + (email or empty) + '|' +
8	 * householdId}. Two owners are duplicates only when their whole identityKey is equal, so members of
9	 * the same household (same householdId) with different telephones have distinct keys.
10	 */
11	public final class OwnerIdentity {
12	
13	    private OwnerIdentity() {
14	    }
15	
16	    public static String key(Owner owner) {
17	        return orEmpty(owner.getTelephone()) + "|" + orEmpty(owner.getEmail()) + "|"
18	                + orEmpty(owner.getHouseholdId());
19	    }
20	
21	    private static String orEmpty(String value) {
22	        return value == null ? "" : value;
23	    }
24	}
