3	import java.util.Set;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailException;
8	
9	/**
10	 * Rejects a new owner whose email domain is on the disposable-domain blocklist. Runs after Build so the
11	 * email is already normalized to lower case by {@link Owner#setEmail}, and before Save so the reject is a
12	 * 400 rather than a persisted owner.
13	 */
14	public class RejectDisposableEmail {
15	
16	    private static final Set<String> BLOCKED = Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
17	
18	    public void service(@Val Owner owner) throws DisposableEmailException {
19	        String email = owner.getEmail();
20	        if (email == null) {
21	            return;
22	        }
23	        int at = email.lastIndexOf('@');
24	        if (at >= 0 && BLOCKED.contains(email.substring(at + 1))) {
25	            throw new DisposableEmailException(email);
26	        }
27	    }
28	}
