8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * De-duplicates the {@code customerCode} assigned by {@link AssignCustomerCode}. When the computed
12	 * code already belongs to an existing owner, appends {@code -<n>} with the smallest {@code n} of 2 or
13	 * more that makes it unique. Runs after Assign and before Save, so distinct owners always persist
14	 * distinct customerCodes.
15	 */
16	public class DeduplicateCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String base = owner.getCustomerCode();
20	        Set<String> taken = new HashSet<>();
21	        for (Owner existing : ownerRepository.findAll()) {
22	            taken.add(existing.getCustomerCode());
23	        }
24	        String code = base;
25	        for (int n = 2; taken.contains(code); n++) {
26	            code = base + "-" + n;
27	        }
28	        owner.setCustomerCode(code);
29	    }
30	}
